<script setup>
import { computed, ref } from 'vue'
import { stories } from '../data/stories.js'
import { session } from '../stores/session.js'
const province = ref('全部地区')
const list = computed(() => stories.filter(story => province.value === '全部地区' || story.province === province.value))
const count = computed(() => stories.filter(story => session.progress.stories[story.id]?.collected).length)
</script>
<template><section class="page collection-page"><div class="collection-heading"><div><h1>巷口拾遗</h1><p>带回来的，不只有味道。<br>把偶遇的故事，收进这一本手记。</p></div><div class="collection-count"><strong>{{ count }}</strong><span>/ {{ stories.length }} 件纪念物</span></div></div><div class="filter-bar"><label>地区<select v-model="province"><option>全部地区</option><option v-for="item in [...new Set(stories.map(story => story.province))]" :key="item">{{ item }}</option></select></label></div><div class="collection-shelf"><template v-for="story in list" :key="story.id"><div v-if="session.progress.stories[story.id]?.collected"><RouterLink class="ticket collected-ticket" :to="'/story/' + story.id"><span>{{ story.province }} · 巷口故事</span><strong>{{ story.memento.name }}</strong><p>{{ story.memento.line }}</p><span class="ticket-stamp">已珍藏</span><span class="ticket-action">翻开故事 →</span></RouterLink><RouterLink class="text-link" :to="'/food/' + story.foodId">回到关联美食 →</RouterLink></div><div v-else class="unfound-object"><div class="paper-outline" aria-hidden="true">？</div><h2>{{ session.progress.stories[story.id]?.found ? '有一段故事，还没读完' : '一件小物，还在巷子里' }}</h2><p>{{ story.province }}的一张纸片，藏着一段日常。</p><RouterLink class="text-link" :to="session.progress.stories[story.id]?.found ? '/story/' + story.id : '/province/' + story.province">{{ session.progress.stories[story.id]?.found ? '继续读故事' : '去当地找找' }} ↗</RouterLink></div></template><div class="shelf-note"><span class="handwritten">每一次发现，<br>都是与一座城的重逢。</span><p>留意纸条的翘角与器物旁的细节，<br>故事会在你亲手翻开时开始。</p></div></div><p class="local-note">探索记录仅保存在当前浏览器，清除浏览器数据后会丢失。</p></section></template>
